import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Hero from './components/Hero';
import ProductsList from './components/ProductsList';
import SupportSection from './components/SupportSection';
import AboutSection from './components/AboutSection';
import ProductDetailModal from './components/ProductDetailModal';
import CartModal from './components/CartModal';
import QuickSearchModal from './components/QuickSearchModal';
import { sounds } from './utils/sound';
import { downloadRobloxPlaceFile } from './utils/robloxDownload';

export default function App() {
  const [activeTab, setActiveTab] = useState('home');
  const [cart, setCart] = useState([]);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [cartOpen, setCartOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [currency, setCurrency] = useState('USD');
  const [activeTicketId, setActiveTicketId] = useState(null);
  const [initialOrderRef, setInitialOrderRef] = useState('');
  const [toastMessage, setToastMessage] = useState(null);

  // Global hotkeys (Ctrl+K or Cmd+K for search)
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setSearchOpen(prev => !prev);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => {
      setToastMessage((current) => (current === msg ? null : current));
    }, 3200);
  };

  const handleAddToCart = (product) => {
    setCart((prev) => [...prev, product]);
    sounds.playPop();
    showToast(`Added "${product.title}" to your cart`);
  };

  const handleRemoveFromCart = (productId) => {
    setCart((prev) => prev.filter(p => p.id !== productId));
    sounds.playPop();
  };

  const handleClearCart = () => {
    setCart([]);
  };

  const handleInstantBuy = (product) => {
    sounds.playPop();
    // Add to cart and open cart modal directly
    setCart((prev) => {
      if (!prev.some(p => p.id === product.id)) {
        return [...prev, product];
      }
      return prev;
    });
    setCartOpen(true);
  };

  const handleOpenSupportWithOrder = (orderNumber) => {
    setInitialOrderRef(orderNumber);
    setActiveTicketId(null);
    setActiveTab('support');
    showToast(`Support opened with Order #${orderNumber}`);
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-[#f4f4f5] flex flex-col justify-between selection:bg-[#ef233c] selection:text-white relative">
      {/* Navbar */}
      <Navbar
        activeTab={activeTab}
        setActiveTab={(tab) => {
          setActiveTab(tab);
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }}
        cartCount={cart.length}
        onOpenCart={() => {
          setCartOpen(true);
          sounds.playPop();
        }}
        onOpenSearch={() => {
          setSearchOpen(true);
          sounds.playPop();
        }}
        currency={currency}
        setCurrency={setCurrency}
      />

      {/* Main Content View */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex-1 w-full">
        {activeTab === 'home' && (
          <Hero
            onBrowseProducts={() => {
              setActiveTab('products');
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
            onOpenProduct={(prod) => {
              setSelectedProduct(prod);
              sounds.playPop();
            }}
            onOpenSupport={() => {
              setActiveTab('support');
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
            onSelectTicket={(tId) => {
              setActiveTicketId(tId);
              setActiveTab('support');
            }}
          />
        )}

        {activeTab === 'products' && (
          <ProductsList
            onOpenProduct={(prod) => {
              setSelectedProduct(prod);
              sounds.playPop();
            }}
            onAddToCart={handleAddToCart}
            onInstantBuy={handleInstantBuy}
          />
        )}

        {activeTab === 'support' && (
          <SupportSection
            activeTicketId={activeTicketId}
            setActiveTicketId={setActiveTicketId}
            initialOrderRef={initialOrderRef}
          />
        )}

        {activeTab === 'about' && (
          <AboutSection
            onOpenSupport={() => {
              setActiveTab('support');
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
          />
        )}
      </main>

      {/* Footer */}
      <Footer setActiveTab={setActiveTab} />

      {/* Modals & Drawers */}
      <ProductDetailModal
        product={selectedProduct}
        onClose={() => setSelectedProduct(null)}
        onAddToCart={handleAddToCart}
        onInstantBuy={handleInstantBuy}
      />

      <CartModal
        isOpen={cartOpen}
        onClose={() => setCartOpen(false)}
        cart={cart}
        onRemoveFromCart={handleRemoveFromCart}
        onClearCart={handleClearCart}
        onOpenSupportWithOrder={handleOpenSupportWithOrder}
      />

      <QuickSearchModal
        isOpen={searchOpen}
        onClose={() => setSearchOpen(false)}
        onSelectProduct={(p) => {
          setSelectedProduct(p);
          sounds.playPop();
        }}
        onSelectTicket={(tId) => {
          setActiveTicketId(tId);
          setActiveTab('support');
        }}
      />

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 bg-[#16161c] text-white text-xs font-medium px-4 py-3 rounded-xl border border-[#2e2e38] shadow-2xl flex items-center space-x-2 animate-in slide-in-from-bottom-3 duration-200">
          <span className="w-2 h-2 rounded-full bg-[#ef233c] animate-ping"></span>
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Trash2, ShieldCheck, Download, Zap, CheckCircle2, ArrowRight, RefreshCw, CreditCard } from 'lucide-react';
import confetti from 'canvas-confetti';
import { downloadRobloxPlaceFile } from '../utils/robloxDownload';
import { sounds } from '../utils/sound';

export default function CartModal({ isOpen, onClose, cart, onRemoveFromCart, onClearCart, onOpenSupportWithOrder }) {
  const [paymentMethod, setPaymentMethod] = useState('paypal');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderComplete, setOrderComplete] = useState(null);
  const [email, setEmail] = useState('');

  if (!isOpen) return null;

  const total = cart.reduce((acc, item) => acc + item.price, 0);

  const handleCheckout = (e) => {
    e.preventDefault();
    if (cart.length === 0) return;

    setIsProcessing(true);
    sounds.playPop();

    setTimeout(() => {
      setIsProcessing(false);
      const randomOrder = `ORD-${Math.floor(10000 + Math.random() * 90000)}`;

      // Complete order
      const orderData = {
        orderNumber: randomOrder,
        items: [...cart],
        total,
        paymentMethod,
        date: new Date().toISOString(),
        customerEmail: email || 'guest_dev@roblox.io'
      };
      setOrderComplete(orderData);

      // Trigger celebration confetti
      try {
        confetti({
          particleCount: 80,
          spread: 70,
          origin: { y: 0.6 }
        });
      } catch (err) {}

      sounds.playSuccess();

      // Automatically trigger downloads for purchased items
      cart.forEach((item, idx) => {
        setTimeout(() => {
          downloadRobloxPlaceFile(item);
        }, idx * 600);
      });

      onClearCart();
    }, 1800);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/75 backdrop-blur-sm">
      <div className="relative w-full max-w-md h-full bg-[#0c0c0f] border-l border-[#1f1f24] shadow-2xl flex flex-col justify-between overflow-hidden">
        {/* Header */}
        <div className="p-5 border-b border-[#1f1f24] flex items-center justify-between">
          <div className="flex items-center space-x-2.5">
            <h2 className="text-lg font-bold text-white">Your Cart</h2>
            <span className="px-2 py-0.5 rounded-full text-xs font-mono font-bold bg-[#ef233c] text-white">
              {cart.length}
            </span>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-5 space-y-5">
          {orderComplete ? (
            /* Order Success View */
            <div className="py-8 text-center space-y-5">
              <div className="w-14 h-14 rounded-full bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 flex items-center justify-center mx-auto">
                <CheckCircle2 className="w-8 h-8" />
              </div>

              <div>
                <h3 className="text-xl font-black text-white">Payment Confirmed!</h3>
                <p className="text-xs text-zinc-400 mt-1">
                  Your files have started downloading automatically (.rbxl).
                </p>
              </div>

              <div className="bg-[#121216] border border-[#27272a] rounded-xl p-4 text-left space-y-2 text-xs font-mono">
                <div className="flex justify-between">
                  <span className="text-zinc-500">Order Ref:</span>
                  <span className="text-amber-400 font-bold">{orderComplete.orderNumber}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500">Total Paid:</span>
                  <span className="text-white">${orderComplete.total.toFixed(2)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500">Method:</span>
                  <span className="uppercase text-zinc-300">{orderComplete.paymentMethod}</span>
                </div>
              </div>

              <div className="space-y-2">
                <p className="text-xs text-zinc-400">
                  Didn't download automatically? Click below to re-download.
                </p>
                {orderComplete.items.map((it) => (
                  <button
                    key={it.id}
                    onClick={() => downloadRobloxPlaceFile(it)}
                    className="w-full py-2 bg-[#18181c] hover:bg-[#23232a] border border-[#27272a] rounded-lg text-xs font-semibold text-white flex items-center justify-center space-x-2 transition-colors"
                  >
                    <Download className="w-3.5 h-3.5" />
                    <span>Download {it.title} (.rbxl)</span>
                  </button>
                ))}
              </div>

              <div className="pt-4 border-t border-[#1f1f24] space-y-2">
                <button
                  onClick={() => {
                    onOpenSupportWithOrder(orderComplete.orderNumber);
                    onClose();
                  }}
                  className="w-full py-2.5 bg-[#ef233c] hover:bg-[#d90429] text-white text-xs font-bold rounded-lg transition-colors shadow-sm flex items-center justify-center space-x-1.5"
                >
                  <span>Need help? Open support ticket</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => {
                    setOrderComplete(null);
                    onClose();
                  }}
                  className="w-full py-2 text-xs text-zinc-400 hover:text-white"
                >
                  Continue shopping
                </button>
              </div>
            </div>
          ) : cart.length === 0 ? (
            /* Empty Cart View */
            <div className="py-20 text-center space-y-3">
              <div className="w-12 h-12 rounded-xl bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-500 mx-auto">
                <Zap className="w-5 h-5 text-zinc-500" />
              </div>
              <p className="text-sm font-semibold text-white">Your cart is empty</p>
              <p className="text-xs text-zinc-500 max-w-xs mx-auto">
                Browse our builds and add combat engines, complete games or VFX systems to your cart.
              </p>
            </div>
          ) : (
            /* Cart Items */
            <div className="space-y-4">
              <div className="space-y-2.5">
                {cart.map((item) => (
                  <div
                    key={item.id}
                    className="bg-[#121216] border border-[#222228] rounded-xl p-3.5 flex items-center justify-between"
                  >
                    <div className="space-y-0.5 max-w-[220px]">
                      <h4 className="text-xs font-bold text-white line-clamp-1">{item.title}</h4>
                      <div className="text-[10px] text-zinc-500 font-mono">{item.fileType}</div>
                      <div className="text-xs font-bold text-[#ef233c]">${item.price.toFixed(2)}</div>
                    </div>

                    <button
                      onClick={() => onRemoveFromCart(item.id)}
                      className="p-1.5 text-zinc-500 hover:text-red-400 transition-colors"
                      title="Remove item"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>

              {/* Payment selector */}
              <div className="pt-4 border-t border-[#1f1f24] space-y-3">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-400">
                  Payment Method (Instant Delivery)
                </label>

                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    onClick={() => setPaymentMethod('paypal')}
                    className={`p-3 rounded-lg border text-xs font-medium flex items-center justify-center space-x-2 transition-all ${
                      paymentMethod === 'paypal'
                        ? 'border-[#ef233c] bg-[#ef233c]/10 text-white'
                        : 'border-[#222228] bg-[#121216] text-zinc-400 hover:text-white'
                    }`}
                  >
                    <span>🅿️ PayPal</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => setPaymentMethod('crypto')}
                    className={`p-3 rounded-lg border text-xs font-medium flex items-center justify-center space-x-2 transition-all ${
                      paymentMethod === 'crypto'
                        ? 'border-[#ef233c] bg-[#ef233c]/10 text-white'
                        : 'border-[#222228] bg-[#121216] text-zinc-400 hover:text-white'
                    }`}
                  >
                    <span>₿ Crypto (BTC/SOL)</span>
                  </button>
                </div>

                <div className="space-y-1">
                  <label className="text-[11px] font-mono text-zinc-400">
                    Delivery Email (optional for receipt)
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="you@example.com (no password needed)"
                    className="w-full px-3 py-2 bg-[#121216] border border-[#27272a] focus:border-[#ef233c] text-white text-xs rounded-lg placeholder-zinc-600 focus:outline-none"
                  />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer Checkout Bar */}
        {!orderComplete && cart.length > 0 && (
          <div className="p-5 border-t border-[#1f1f24] bg-[#0c0c0f] space-y-3">
            <div className="flex items-center justify-between text-sm">
              <span className="text-zinc-400">Total</span>
              <span className="text-xl font-black text-white">${total.toFixed(2)}</span>
            </div>

            <button
              onClick={handleCheckout}
              disabled={isProcessing}
              className="w-full py-3 bg-[#ef233c] hover:bg-[#d90429] disabled:opacity-50 text-white text-xs font-bold rounded-lg transition-all shadow-[0_0_20px_rgba(239,35,60,0.3)] flex items-center justify-center space-x-2"
            >
              {isProcessing ? (
                <>
                  <RefreshCw className="w-4 h-4 animate-spin" />
                  <span>Verifying payment gateway...</span>
                </>
              ) : (
                <>
                  <ShieldCheck className="w-4 h-4" />
                  <span>Pay with {paymentMethod === 'paypal' ? 'PayPal' : 'Crypto'} (${total.toFixed(2)})</span>
                </>
              )}
            </button>

            <div className="text-[10px] text-zinc-400 text-center flex items-center justify-center space-x-1">
              <ShieldCheck className="w-3 h-3 text-emerald-400" />
              <span>Instant download starts automatically upon completion.</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { ShoppingBag, Search, Sparkles, DollarSign } from 'lucide-react';

export default function Navbar({ activeTab, setActiveTab, cartCount, onOpenCart, onOpenSearch, currency, setCurrency }) {
  return (
    <header className="sticky top-0 z-40 w-full border-b border-[#18181b] bg-[#09090b]/90 backdrop-blur-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
        {/* Brand */}
        <div className="flex items-center space-x-8">
          <button 
            onClick={() => setActiveTab('home')}
            className="flex items-center space-x-3 group focus:outline-none"
          >
            <div className="w-8 h-8 rounded-lg bg-[#18181b] border border-[#27272a] group-hover:border-[#ef233c]/60 flex items-center justify-center font-bold text-white text-base transition-colors shadow-sm">
              <span className="text-[#ef233c] font-black group-hover:scale-110 transition-transform">A</span>
            </div>
            <span className="font-extrabold tracking-wider text-white text-lg">ATLAS</span>
          </button>

          {/* Nav links */}
          <nav className="hidden md:flex items-center space-x-1">
            <button
              onClick={() => setActiveTab('products')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${
                activeTab === 'products'
                  ? 'text-[#ef233c]'
                  : 'text-zinc-400 hover:text-white hover:bg-zinc-900/60'
              }`}
            >
              Products
            </button>
            <button
              onClick={() => setActiveTab('support')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${
                activeTab === 'support'
                  ? 'text-[#ef233c]'
                  : 'text-zinc-400 hover:text-white hover:bg-zinc-900/60'
              }`}
            >
              Support
            </button>
            <button
              onClick={() => setActiveTab('about')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${
                activeTab === 'about'
                  ? 'text-[#ef233c]'
                  : 'text-zinc-400 hover:text-white hover:bg-zinc-900/60'
              }`}
            >
              About
            </button>
          </nav>
        </div>

        {/* Right Actions */}
        <div className="flex items-center space-x-2 sm:space-x-3">
          {/* Mobile nav triggers */}
          <div className="flex md:hidden items-center space-x-1 text-xs">
            <button
              onClick={() => setActiveTab('products')}
              className={`px-2 py-1 rounded ${activeTab === 'products' ? 'text-[#ef233c] font-semibold' : 'text-zinc-400'}`}
            >
              Products
            </button>
            <button
              onClick={() => setActiveTab('support')}
              className={`px-2 py-1 rounded ${activeTab === 'support' ? 'text-[#ef233c] font-semibold' : 'text-zinc-400'}`}
            >
              Support
            </button>
            <button
              onClick={() => setActiveTab('about')}
              className={`px-2 py-1 rounded ${activeTab === 'about' ? 'text-[#ef233c] font-semibold' : 'text-zinc-400'}`}
            >
              About
            </button>
          </div>

          {/* Quick Search */}
          <button
            onClick={onOpenSearch}
            className="p-2 text-zinc-400 hover:text-white hover:bg-[#18181b] rounded-lg border border-transparent hover:border-[#27272a] transition-colors"
            title="Search products"
          >
            <Search className="w-4 h-4" />
          </button>

          {/* Currency / Region pill */}
          <button
            onClick={() => setCurrency(currency === 'USD' ? 'EUR' : currency === 'EUR' ? 'ROBUX' : 'USD')}
            className="hidden sm:flex items-center space-x-1 px-2.5 py-1 text-xs font-mono font-medium text-zinc-400 hover:text-zinc-200 bg-[#141416] hover:bg-[#1c1c1f] rounded-lg border border-[#27272a] transition-colors"
            title="Switch Currency / Value Display"
          >
            <span className="text-zinc-500 text-[10px]">CUR</span>
            <span className="text-zinc-300 font-bold">{currency}</span>
          </button>

          {/* Cart Button */}
          <button
            onClick={onOpenCart}
            className="relative p-2 text-zinc-300 hover:text-white bg-[#141416] hover:bg-[#1e1e24] rounded-lg border border-[#27272a] hover:border-[#3f3f46] transition-colors"
            title="Shopping Cart"
          >
            <ShoppingBag className="w-4 h-4" />
            {cartCount > 0 && (
              <span className="absolute -top-1.5 -right-1.5 bg-[#ef233c] text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center animate-pulse">
                {cartCount}
              </span>
            )}
          </button>
        </div>
      </div>
    </header>
  );
}

import React, { useState } from 'react';
import { X, Star, Download, ShoppingBag, Zap, ShieldCheck, Code2, CheckCircle2, Copy, Check } from 'lucide-react';
import { sounds } from '../utils/sound';

export default function ProductDetailModal({ product, onClose, onAddToCart, onInstantBuy }) {
  const [copiedSnippet, setCopiedSnippet] = useState(false);
  const [activeTab, setActiveTab] = useState('overview');

  if (!product) return null;

  const handleCopyCode = () => {
    if (product.codeSnippet) {
      navigator.clipboard.writeText(product.codeSnippet);
      setCopiedSnippet(true);
      sounds.playPop();
      setTimeout(() => setCopiedSnippet(false), 2000);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6 bg-black/80 backdrop-blur-md overflow-y-auto">
      <div className="relative w-full max-w-3xl bg-[#0e0e12] border border-[#27272a] rounded-2xl shadow-2xl overflow-hidden my-auto">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 z-10 p-2 rounded-full bg-black/60 hover:bg-black/90 text-zinc-400 hover:text-white border border-white/10 transition-colors"
        >
          <X className="w-4 h-4" />
        </button>

        {/* Media Hero */}
        <div className="relative h-60 sm:h-72 w-full bg-zinc-950 overflow-hidden">
          <img
            src={product.previewImage}
            alt={product.title}
            className="w-full h-full object-cover opacity-85"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0e0e12] via-[#0e0e12]/40 to-transparent"></div>

          <div className="absolute bottom-5 left-5 right-5 flex flex-wrap items-end justify-between gap-3">
            <div>
              <div className="flex items-center space-x-2 mb-1.5">
                <span className="px-2.5 py-0.5 rounded-full text-xs font-mono font-medium bg-[#ef233c] text-white">
                  {product.badge}
                </span>
                <span className="px-2.5 py-0.5 rounded bg-black/80 text-xs font-mono text-zinc-300 border border-white/10">
                  {product.fileType}
                </span>
                <span className="px-2.5 py-0.5 rounded bg-black/80 text-xs font-mono text-emerald-400 border border-white/10 flex items-center space-x-1">
                  <ShieldCheck className="w-3.5 h-3.5" />
                  <span>Verified Clean</span>
                </span>
              </div>
              <h2 className="text-2xl sm:text-3xl font-extrabold text-white">{product.title}</h2>
            </div>

            <div className="bg-black/80 backdrop-blur-md border border-white/10 rounded-xl px-4 py-2 text-right">
              <div className="text-2xl font-black text-white">${product.price.toFixed(2)}</div>
              <div className="text-[10px] text-zinc-400">One-time payment</div>
            </div>
          </div>
        </div>

        {/* Tab navigation */}
        <div className="flex items-center space-x-4 px-6 border-b border-[#1f1f24] text-xs font-medium">
          <button
            onClick={() => setActiveTab('overview')}
            className={`py-3 border-b-2 transition-colors ${
              activeTab === 'overview'
                ? 'border-[#ef233c] text-white font-bold'
                : 'border-transparent text-zinc-400 hover:text-zinc-200'
            }`}
          >
            Overview & Features
          </button>
          <button
            onClick={() => setActiveTab('code')}
            className={`py-3 border-b-2 transition-colors ${
